/**
 * retryMergePR.js
 *
 * Called by SM when a Story/Bug ticket is in "In Review" with label "pr_approved".
 * Checks if the GitHub PR is now mergeable (CI passed, no conflicts) and merges it.
 *
 * Outcomes:
 *  - CI still running / blocked → do nothing, release lock so SM retries next cycle
 *  - Merged successfully      → remove pr_approved label (GitHub + Jira), move ticket to Merged
 *  - Conflict / CI failing    → remove pr_approved label, move ticket to In Rework, post comment
 */

const { LABELS } = require('./config.js');
var scmModule = require('./common/scm.js');
var configLoader = require('./configLoader.js');
var autoStart = require('./common/autoStart.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}


function getGitHubRepoInfo() {
    try {
        const rawOutput = cli_execute_command({ command: 'git config --get remote.origin.url' }) || '';
        const remoteUrl = rawOutput.split('\n')
            .map(function(l) { return l.trim(); })
            .filter(function(l) { return l.indexOf('github.com') !== -1; })[0] || '';
        const match = remoteUrl.match(/github\.com[:/]([^/]+)\/([^/?#\s]+)/);
        if (!match) return null;
        return { owner: match[1], repo: match[2].replace(/\.git$/, '') };
    } catch (e) {
        console.error('Failed to get repo info:', e);
        return null;
    }
}

function findPRForTicket(scm, ticketKey) {
    try {
        const prList = scm.listPrs('open');
        const matched = (Array.isArray(prList) ? prList : []).find(function(pr) {
            const titleMatch = pr.title && pr.title.indexOf(ticketKey) !== -1;
            const branchMatch = pr.head && pr.head.ref && pr.head.ref.indexOf(ticketKey) !== -1;
            return titleMatch || branchMatch;
        });
        return matched || null;
    } catch (e) {
        console.error('Failed to list PRs:', e);
        return null;
    }
}

function removeApprovedLabels(scm, prNumber, ticketKey) {
    try {
        scm.removeLabel(prNumber, LABELS.PR_APPROVED);
        console.log('Removed pr_approved label from PR');
    } catch (e) {
        console.warn('Could not remove pr_approved from PR:', e);
    }
    try {
        getTracker().removeLabel(ticketKey, LABELS.PR_APPROVED);
        console.log('Removed pr_approved label from Jira ticket');
    } catch (e) {
        console.warn('Could not remove pr_approved from Jira ticket:', e);
    }
}

function releaseLock(ticketKey, customParams) {
    const removeLabel = customParams && customParams.removeLabel;
    if (removeLabel && ticketKey) {
        try { getTracker().removeLabel(ticketKey, removeLabel); } catch (e) {}
    }
}

function resolveMergeJobName(params, customParams) {
    var metadata = (params.jobParams && params.jobParams.metadata) || params.metadata || {};
    if (metadata.contextId === 'retry_merge_test' || (customParams && customParams.testCaseMerge)) {
        return 'retry_merge_test';
    }
    return 'retry_merge';
}

function resolveCustomParams(params, config) {
    var runtime = (params.jobParams && params.jobParams.customParams) ||
        params.customParams ||
        {};
    var jobName = resolveMergeJobName(params, runtime);
    var merged = {};
    var patch = configLoader.resolveInstructions(jobName, null, config).jobParamPatch;
    if (patch && patch.customParams) {
        Object.assign(merged, patch.customParams);
    }
    Object.assign(merged, runtime);
    return merged;
}

function triggerAutoStartRework(ticketKey, customParams, config, scm) {
    if (!customParams || !customParams.autoStartRework || !customParams.autoStartReworkConfigFile) {
        return false;
    }
    try {
        return autoStart.triggerConfiguredWorkflowForTicket({
            ticketKey: ticketKey,
            customParams: customParams,
            config: config,
            configFile: customParams.autoStartReworkConfigFile,
            label: 'pr_rework',
            scm: scm,
            stripKeys: [
                'removeLabel',
                'autoStartRework',
                'autoStartReworkConfigFile'
            ]
        });
    } catch (e) {
        console.warn('⚠️ autoStartRework trigger failed:', e.message || e);
        return false;
    }
}

// ── gh-980: pure decision helpers extracted from action() (CRAP 190 → 30) ──
// The merge-readiness branch table, verbatim semantics: 'retry' covers
// GitHub's still-computing / CI-running states and a null mergeable,
// 'updateBranch' the behind-base case, 'conflict' every pre-merge conflict
// signal, 'merge' everything else.
var RETRY_MERGE_STATES = {
    unknown: true, blocked: true, unstable: true, checking: true,
    unchecked: true, preparing: true, ci_must_pass: true, ci_still_running: true
};
var CONFLICT_MERGE_STATES = { cannot_be_merged: true, conflict: true };

function decideMergeReadiness(mergeable, mergeableState) {
    if (mergeable === null || RETRY_MERGE_STATES[mergeableState]) return 'retry';
    if (mergeableState === 'behind') return 'updateBranch';
    if (mergeable === false && mergeableState === 'dirty') return 'conflict';
    if (CONFLICT_MERGE_STATES[mergeableState]) return 'conflict';
    return 'merge';
}

function isCiBlockingMessage(errMsg) {
    return errMsg.indexOf('blocked') !== -1 || errMsg.indexOf('422') !== -1 || errMsg.indexOf('405') !== -1;
}

// The merge-error classification, verbatim semantics: a message mentioning
// 'conflict' (case-insensitive) is a conflict; an empty or CI-blocking
// message is a temporary block (retry next cycle, keep pr_approved);
// anything else is a hard failure → In Rework.
function classifyMergeError(mergeErr) {
    var errMsg = mergeErr ? String(mergeErr) : '';
    if (errMsg.toLowerCase().indexOf('conflict') !== -1) return 'conflict';
    if (errMsg === '' || isCiBlockingMessage(errMsg)) return 'temporary';
    return 'ci-failing';
}

// The shared In-Rework escalation: strip pr_approved (SCM + tracker),
// release the SM lock, post the caller-built comment, move the ticket,
// re-arm the rework leg. Called by both the pre-merge conflict path and
// the post-merge-failure path.
function escalateToInRework(opts) {
    removeApprovedLabels(opts.scm, opts.prNumber, opts.ticketKey);
    releaseLock(opts.ticketKey, opts.customParams);
    getTracker().postComment(opts.ticketKey, opts.commentBody);
    getTracker().moveToStatus(opts.ticketKey, opts.config.jira.statuses.IN_REWORK);
    console.log('✅ Ticket moved to In Rework (' + opts.reason + ')');
    triggerAutoStartRework(opts.ticketKey, opts.customParams, opts.config, opts.scm);
}

// Cosmetic label strips around a successful merge — each best-effort with
// its own warning, exactly the historical log lines.
function stripMergedPrLabel(scm, prNumber) {
    try {
        scm.removeLabel(prNumber, LABELS.PR_APPROVED);
        console.log('Removed pr_approved label from GitHub PR');
    } catch (e) {
        console.warn('Could not remove pr_approved from GitHub PR:', e);
    }
}

function stripApprovedLabelAfterMerge(ticketKey) {
    try {
        getTracker().removeLabel(ticketKey, LABELS.PR_APPROVED);
        console.log('Removed pr_approved label from Jira ticket');
    } catch (e) {
        console.warn('Could not remove pr_approved from Jira ticket:', e);
    }
}

// gh-916: Passed/Failed/Merged can be tag-only (restricted ADO workflows) —
// stage-label fallback on a rejected transition.
function resolveTestCaseFinalStatus(ticketKey, jiraConfig) {
    var ticketDetail = getTracker().getIssue(ticketKey);
    // hasStage also accepts the stage_in_review_passed marker a rejected transition
    // left (jira.stageFallback 'label'); 'none' mode compares the status only.
    var wasReviewPassed = getTracker().hasStage(ticketDetail, 'IN_REVIEW_PASSED', jiraConfig.statuses.IN_REVIEW_PASSED);
    var finalStatus = wasReviewPassed ? jiraConfig.statuses.PASSED : jiraConfig.statuses.FAILED;
    var moved = getTracker().moveToStatusOrMark(ticketKey, finalStatus, wasReviewPassed ? 'PASSED' : 'FAILED');
    if (moved.moved || moved.marked) {
        console.log('✅ Ticket moved to ' + finalStatus);
    }
}

function moveTicketToMerged(ticketKey, jiraConfig) {
    var mergedMove = getTracker().moveToStatusOrMark(ticketKey, jiraConfig.statuses.MERGED, 'MERGED');
    if (mergedMove.moved || mergedMove.marked) {
        console.log('✅ Ticket moved to Merged');
    }
}

// Post-merge finalization: move the ticket to its final status BEFORE
// removing pr_approved from Jira. Jira's search index can lag: if the status
// update hasn't propagated yet when the next SM rule runs its JQL, the
// ticket would still appear as "In Review". Keeping pr_approved on the Jira
// ticket until after the status move means the review-trigger rule (JQL:
// NOT IN pr_approved) naturally skips the ticket.
function finalizeMergedTicket(params, ticketKey, jiraConfig) {
    var isTestCase = params.jobParams && params.jobParams.customParams && params.jobParams.customParams.testCaseMerge;
    if (isTestCase) {
        resolveTestCaseFinalStatus(ticketKey, jiraConfig);
    } else {
        moveTicketToMerged(ticketKey, jiraConfig);
    }
}

function action(params) {
    const ticketKey = params.ticket && params.ticket.key;
    if (!ticketKey) {
        console.error('No ticketKey provided');
        return false;
    }

    var config = configLoader.loadProjectConfig(params.jobParams || params);
    var jiraConfig = config.jira;
    var scm = scmModule.createScm(config);
    var customParams = resolveCustomParams(params, config);
    initTracker(config, customParams);

    const repoInfo = scm.getRemoteRepoInfo();
    if (!repoInfo) {
        console.error('Could not determine owner/repo');
        releaseLock(ticketKey, customParams);
        return false;
    }
    const { owner, repo } = repoInfo;

    const pr = findPRForTicket(scm, ticketKey);
    if (!pr) {
        console.warn('No open PR found for ticket ' + ticketKey + ' — releasing lock');
        releaseLock(ticketKey, customParams);
        return false;
    }

    const prNumber = pr.number;
    const prUrl = pr.html_url;
    console.log('Found PR #' + prNumber + ' for ticket ' + ticketKey);

    // Check PR mergeable status
    let mergeableState = null;
    let mergeable = null;
    try {
        const prDetail = scm.getPr(prNumber);
        mergeable = prDetail && prDetail.mergeable;
        mergeableState = prDetail && prDetail.mergeable_state;
        console.log('PR mergeable: ' + mergeable + ', state: ' + mergeableState);
    } catch (e) {
        console.warn('Could not get PR details, will attempt merge anyway:', e);
    }

    // GitHub hasn't computed mergeability yet, or CI checks still running — retry next cycle
    var readiness = decideMergeReadiness(mergeable, mergeableState);
    if (readiness === 'retry') {
        console.log('PR not ready to merge (' + mergeableState + ') — will retry next cycle');
        return false;
    }

    // PR branch is behind base — update it so CI can re-run, then retry next cycle
    if (readiness === 'updateBranch') {
        console.log('PR branch is behind base — requesting branch update');
        try {
            if (scm.updateBranch) {
                scm.updateBranch(prNumber, owner, repo);
            } else {
                throw new Error('SCM provider does not support updateBranch');
            }
            console.log('Branch update requested — will retry merge next cycle after CI passes');
        } catch (updateErr) {
            console.warn('Could not update branch (may already be updating):', updateErr);
        }
        return false;
    }

    // Conflict detected before attempting merge
    if (readiness === 'conflict') {
        console.log('PR has merge conflict — moving ticket to In Rework');
        escalateToInRework({
            scm: scm,
            prNumber: prNumber,
            ticketKey: ticketKey,
            customParams: customParams,
            config: config,
            reason: 'merge conflict',
            commentBody: '{panel:bgColor=#FFEBE6|borderColor=#DE350B}⚠️ *MERGE CONFLICT* — PR #' + prNumber + ' has a merge conflict with main. Please resolve conflicts and re-push.\n\n[View PR|' + prUrl + ']{panel}'
        });
        return true;
    }

    // Attempt merge
    try {
        scm.mergePr(prNumber, 'squash');
        console.log('✅ PR #' + prNumber + ' merged successfully');

        // Remove GitHub PR label immediately (cosmetic — PR is closed)
        stripMergedPrLabel(scm, prNumber);
        releaseLock(ticketKey, customParams);

        finalizeMergedTicket(params, ticketKey, jiraConfig);

        // Now safe to remove pr_approved from Jira — status is already updated
        stripApprovedLabelAfterMerge(ticketKey);
        return true;
    } catch (mergeErr) {
        console.warn('Merge failed:', mergeErr);
        var failure = classifyMergeError(mergeErr);

        if (failure === 'temporary') {
            // Temporary block — retry next cycle, keep pr_approved
            console.log('Merge blocked temporarily — will retry next cycle');
            return false;
        }

        var reason = failure === 'conflict' ? 'merge conflict' : 'CI checks failing or PR not mergeable';
        escalateToInRework({
            scm: scm,
            prNumber: prNumber,
            ticketKey: ticketKey,
            customParams: customParams,
            config: config,
            reason: reason,
            commentBody: '{panel:bgColor=#FFEBE6|borderColor=#DE350B}⚠️ *MERGE FAILED* — Could not merge PR #' + prNumber + ': ' + reason + '. Please check and re-push.\n\n[View PR|' + prUrl + ']{panel}'
        });

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return true;
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action, resolveCustomParams, triggerAutoStartRework, decideMergeReadiness, classifyMergeError };
}

/**
 * mergeBot — event-driven fast path for the machine loop's merge stage.
 *
 * The SM tick (cron every-10-minutes) is best-effort: GitHub silently drops scheduled
 * runs under load (live: fa ticks vanished for 30+ min while approved
 * green PRs waited). This bot runs on EVENTS — CI conclusion
 * (workflow_run), label changes / head pushes (pull_request), check-run
 * completions, and manual dispatch — and performs exactly the
 * deterministic, idempotent stage transitions that need no orchestration:
 *
 *   approved + ai_validating + green + CLEAN  -> squash-merge (retry once
 *                                                on transient API errors)
 *   ai_validating + green + CLEAN + !approved-> latch ai_validated, unarm
 *   ai_validating + green + base moved       -> unarm (stale head; the SM
 *                                                refreshes + re-validates)
 *
 * Everything else (validation dispatch, review/rework legs, conflict
 * rework, fail-validation reporting) stays SM-owned: the bot never
 * dispatches workflows, never arms labels beyond the two latches above —
 * it only CONCLUDES stages whose evidence is already on the PR.
 *
 * One exception (owner rule 2026-10-04): a deferred approved PR with
 * acted==0 at end-of-run fires a single machine-sm.yml tick (self-heal,
 * 'gh workflow run machine-sm.yml -F dryRun=false --repo owner/name'),
 * skipped when a machine-sm.yml run is already active — see the
 * END-OF-RUN SELF-TICK block in action() and hasActiveSmRun().
 *
 * jsrunner contract: repo comes from params.jobParams.repo
 * ("owner/name") or GH_REPO; tools are the global snake_case bridge.
 */

/* global github_list_prs, github_get_pr, github_get_commit_check_runs,
   github_list_workflow_runs, github_merge_pr, github_add_labels,
   github_remove_label, cli_execute_command */

function parseMcp(raw) {
    if (raw === null || raw === undefined) return {};
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(String(raw)); } catch (e) { return {}; }
}

function labelNames(pr) {
    return (pr.labels || []).map(function (l) { return (l && l.name) || l; });
}

/**
 * The list tools have returned both bare arrays and wrapped objects
 * ({ pullRequests: [...] } / { items: [...] }) across bridge versions.
 * Every consumer normalizes through here: a wrapped payload iterated as
 * a bare array has length undefined, the loop never runs, and the op
 * vanishes from the log (gh-952 review: mergedSlotHolder once iterated
 * the merged list raw — a shape mismatch would have silently disabled
 * the slot release the whole PR exists for).
 */
function listArray(prs) {
    return Array.isArray(prs) ? prs : (prs.pullRequests || prs.items || []);
}

/**
 * Membership test for a normalized label-name list — extracted from
 * action()'s `labels.indexOf('x') !== -1` chains (gh-1040): each inline
 * chain added a decision to action's complexity, and the predicate reads
 * the same everywhere.
 */
function hasLabel(labels, wanted) {
    return labels.indexOf(wanted) !== -1;
}

/**
 * Epoch ms when the run started waiting (check-run started_at, workflow-run
 * created_at) or null when the payload carries no usable timestamp — the
 * gh-766 stale-head detection FAILS OPEN on null (treated as live).
 */
function pendingStartedAt(r) {
    if (!r) return null;
    var raw = r.started_at || r.startedAt || r.created_at || r.createdAt;
    if (!raw) return null;
    var ts = Date.parse(raw);
    return isNaN(ts) ? null : ts;
}

/**
 * Concluded-red conclusions (any case, already upper-cased by the caller).
 */
function isRedConclusion(c) {
    return c === 'FAILURE' || c === 'TIMED_OUT' || c === 'CANCELLED';
}

/**
 * Not-yet-concluded run shapes (gh-1040): no conclusion at all, or an
 * explicitly queued/in-flight status.
 */
function isPendingRunShape(c, s) {
    return !c || s === 'QUEUED' || s === 'IN_PROGRESS' || s === 'WAITING' || s === 'PENDING';
}

/**
 * Per-run classification for rollupDetail (gh-1040): a concluded
 * FAILURE/TIMED_OUT/CANCELLED run is red; a run with no conclusion yet
 * (or an explicitly queued/in-flight status) is pending and carries its
 * start timestamp as motionless-since evidence; anything else is a
 * settled non-failure and contributes nothing.
 */
function decideRunState(r) {
    var c = r.conclusion ? String(r.conclusion).toUpperCase() : null;
    var s = r.status ? String(r.status).toUpperCase() : null;
    if (isRedConclusion(c)) return { red: true, pending: false, started: null };
    if (isPendingRunShape(c, s)) {
        return { red: false, pending: true, started: pendingStartedAt(r) };
    }
    return { red: false, pending: false, started: null };
}

/**
 * Rollup combination (gh-1040): any red run turns the head red; else any
 * pending run makes it pending with the OLDEST pending start as
 * pendingSince (gh-766 motionless evidence); else green.
 */
function combineRunStates(states) {
    var red = false, pending = false, oldestPending = null;
    states.forEach(function (st) {
        if (st.red) { red = true; return; }
        if (!st.pending) return;
        pending = true;
        if (st.started !== null && (oldestPending === null || st.started < oldestPending)) {
            oldestPending = st.started;
        }
    });
    if (red) return { state: 'red', pendingSince: null };
    if (pending) return { state: 'pending', pendingSince: oldestPending };
    return { state: 'green', pendingSince: null };
}

/**
 * Commit-check-runs fetch + PR statusCheckRollup fallback (gh-1040
 * extraction, call order and shapes verbatim): the bridge payload may
 * carry { total_count } without a check_runs array (reads as empty), and
 * the REST PR body's statusCheckRollup — when it is a non-empty ARRAY —
 * is the next evidence rung before the workflow-run fallback.
 */
function fetchCheckRuns(commitSha, pr, owner, name) {
    var cr = parseMcp(github_get_commit_check_runs({
        workspace: owner, repository: name, commitSha: commitSha
    }));
    var runs = cr.check_runs || cr.total_count !== undefined ? (cr.check_runs || []) : [];
    if (!runs.length && pr && Array.isArray(pr.statusCheckRollup) && pr.statusCheckRollup.length) {
        runs = pr.statusCheckRollup;
    }
    return runs;
}

/**
 * Workflow-run evidence for a head sha (gh-1040 extraction): the newest
 * run on the sha decides — SUCCESS green, FAILURE/TIMED_OUT/CANCELLED
 * red, anything else pending with the run's start as pendingSince.
 * Null when no run matches (caller reports 'none').
 */
function workflowRunEvidence(wruns, commitSha) {
    var mine = wruns.filter(function (r) { return String(r.head_sha || r.headSha) === String(commitSha); });
    if (!mine.length) return null;
    // newest first (API order); conclusion decides, in-flight waits
    var top = mine[0];
    var c = top.conclusion ? String(top.conclusion).toUpperCase() : null;
    if (c === 'SUCCESS') return { state: 'green', pendingSince: null };
    if (c === 'FAILURE' || c === 'TIMED_OUT' || c === 'CANCELLED') return { state: 'red', pendingSince: null };
    return { state: 'pending', pendingSince: pendingStartedAt(top) };
}

/**
 * Same rollup as checksRollup, plus pendingSince: the OLDEST start time
 * among the pending evidence (gh-766) — an armed head whose checks have
 * been motionless past staleHeadMinutes is a dead FIFO head (skipped with
 * an explicit log line, unarmed, queue advances) instead of an eternal
 * 'checks=pending — waiting'.
 */
function rollupDetail(commitSha, pr, job, owner, name) {
    var runs = fetchCheckRuns(commitSha, pr, owner, name);
    if (!runs.length) {
        // Workflow-run fallback (live: fa #762): the REST PR body has NO
        // statusCheckRollup (GraphQL-only) and API silent-updated heads carry
        // no check runs — but the SM-dispatched CI run IS on this exact sha.
        // Read the repo's CI workflow runs and match head_sha. The SM's own
        // waiter is a pull_request-event job: it never re-runs on refreshed
        // heads, so this is the ONLY conclusive evidence for them.
        var wf = parseMcp(github_list_workflow_runs({
            workspace: owner, repository: name,
            workflowId: (job && job.ciWorkflow) || 'ci.yml', perPage: 30
        }));
        var wruns = (wf && (wf.workflow_runs || wf.runs)) || [];
        var evidence = workflowRunEvidence(wruns, commitSha);
        if (evidence) return evidence;
        return { state: 'none', pendingSince: null };
    }
    if (!runs.length) return { state: 'none', pendingSince: null };
    return combineRunStates(runs.map(decideRunState));
}

/**
 * Check-rollup for a head sha: 'green' (all concluded SUCCESS), 'red'
 * (any FAILURE/TIMED_OUT/CANCELLED), 'pending' (queued/in flight),
 * 'none' (no evidence at all — nothing concluded anywhere).
 *
 * Fallback (live: fa #762, 2026-09-22): silent-update refreshes a branch
 * via the update-branch API, which fires NO pull_request event — the
 * gate waiter check run never re-runs on the new head, so commit check
 * runs come back EMPTY even though the dispatched CI (check suites) is
 * green on that exact sha. When check runs are empty, fall back to the
 * PR-level statusCheckRollup (suites + statuses aggregated by GitHub)
 * before declaring 'none' — otherwise a green approved CLEAN head waits
 * forever and only the SM tick's better-informed merge can land it.
 */
function checksRollup(commitSha, pr, job, owner, name) {
    return rollupDetail(commitSha, pr, job, owner, name).state;
}

/**
 * mergeState, deterministic (smProvider.prStatus parity, minimal): REST
 * mergeable_state mapped to UPPER, DIRTY on mergeable===false, BEHIND when
 * the base moved (base.sha vs the live base branch head via github_list_prs
 * is unavailable — use mergeable_state 'behind' plus the base sha vs
 * github_get_pr(base).head? The PR body carries base.sha only). For the
 * bot's decisions BEHIND matters only to NOT merge a stale head — REST
 * already reports 'behind' for those; keep BLOCKED (checks pending under
 * protection) and CLEAN as REST says, DIRTY/BEHIND/other as REST says.
 */
// gh-1101 (live dart #435): rollup green + approved + BLOCKED is the
// "required checks invisible to PR" shape (required contexts ran in a
// workflow_dispatch suite) — the SM fresh-sha resets it; say so.
function blockedWaitLine(number, ms, approved) {
    if (ms === 'BLOCKED' && approved) {
        return '⏳ pr-' + number + ' checks green but mergeState=BLOCKED — required checks' +
            ' invisible to PR? (SM fresh-sha reset owns it, gh-1101)';
    }
    return '⏳ pr-' + number + ' mergeState=' + ms + ' — waiting (checks settling)';
}

function mergeStateOf(pr) {
    if (pr.mergeable === false) return 'DIRTY';
    var ms = pr.mergeStateStatus ||
        (pr.mergeable_state ? String(pr.mergeable_state).toUpperCase() : '');
    return ms || (pr.mergeable === true ? 'CLEAN' : 'UNKNOWN');
}

/**
 * Repo resolution (gh-1040 extraction, verbatim behavior): jobParams.repo
 * first, the GH_REPO global second, throws on neither / on a value
 * without an owner/name split.
 */
function resolveRepoTarget(job) {
    var repo = job.repo;
    if (!repo && typeof GH_REPO !== 'undefined') repo = GH_REPO;
    if (!repo) throw new Error('mergeBot: no repo (params.jobParams.repo / GH_REPO)');
    var parts = String(repo).split('/');
    if (parts.length < 2) throw new Error('mergeBot: repo must be owner/name, got ' + repo);
    return { owner: parts[0], name: parts.slice(1).join('/') };
}

/**
 * gh-766 stale-head threshold (default 120 = 2h), verbatim.
 */
function staleHeadMinutesOr(job) {
    return (typeof job.staleHeadMinutes === 'number' && job.staleHeadMinutes > 0)
        ? job.staleHeadMinutes : 120;
}

/**
 * gh-952 merged-slot-holder pre-scan (gh-1040 extraction, same call
 * order: no tracker calls until the merged probe). Returns the
 * recently-merged still-armed holder the open list cannot show, or null.
 */
function findReleasedSlotHolder(list, owner, name) {
    var approvedSeen = list.some(function (p) {
        return hasLabel(labelNames(p), 'pr_approved');
    });
    if (!approvedSeen) return null;
    var armedHolderOpen = list.some(function (p) {
        var ls = labelNames(p);
        return hasLabel(ls, 'ai_validating') && hasLabel(ls, 'pr_approved');
    });
    if (armedHolderOpen) return null;
    return mergedSlotHolder(owner, name);
}

/**
 * machine-sm.yml listing with the PAT-404 fallback (gh-1040 extraction,
 * verbatim semantics): the workflow-id form 404s for some PATs — fall
 * back to the all-runs endpoint and filter by workflow path client-side.
 * Returns null when the listing itself is unlistable (fail open).
 */
function listSmRuns(owner, name) {
    try {
        var wf = parseMcp(github_list_workflow_runs({
            workspace: owner, repository: name,
            workflowId: 'machine-sm.yml', perPage: 30
        }));
        var runs = smRunsFromPayload(wf);
        if (!runs.length && wf && wf.message) {
            runs = allRunsFallback(owner, name);
        }
        return runs;
    } catch (eActive) {
        return null; // unlistable → fail open, the self-heal still fires
    }
}

/**
 * The workflow_runs/runs array of a listing payload, verbatim shapes.
 */
function smRunsFromPayload(payload) {
    return (payload && (payload.workflow_runs || payload.runs)) || [];
}

/**
 * The all-runs-endpoint fallback of the active-SM probe (gh-1040
 * extraction): same call as the primary listing minus the workflowId
 * (that form is what 404s), filtered to machine-sm.yml by run path.
 */
function allRunsFallback(owner, name) {
    var all = parseMcp(github_list_workflow_runs({
        workspace: owner, repository: name, perPage: 30
    }));
    return smRunsFromPayload(all).filter(function (r) {
        return String(r.path || '') === '.github/workflows/machine-sm.yml';
    });
}

/**
 * Live-SM statuses (review #701, already lower-cased by the caller).
 */
function isActiveSmStatus(s) {
    return s === 'queued' || s === 'in_progress' || s === 'waiting' || s === 'pending';
}

/**
 * Zombie stamp of a non-in_progress run (review #701 tick-storm fix,
 * verbatim): the last update timestamp of the run, whatever field the
 * bridge payload carried it in.
 */
function smRunTimestamp(r) {
    return r.updated_at || r.updatedAt || r.created_at || r.createdAt || '';
}

/**
 * Zombie check (gh-1040 extraction): a non-in_progress run whose last
 * update is older than 6h was superseded by its concurrency group and
 * does not count as active. A run with NO parseable timestamp is never a
 * zombie (no evidence of motionlessness — fail open as live).
 */
function isZombieSmRun(r, now) {
    var ts = Date.parse(smRunTimestamp(r));
    return !isNaN(ts) && (now - ts) > 6 * 60 * 60 * 1000;
}

/**
 * Zombie-aware liveness of one workflow run (gh-1040 extraction, review
 * #701 tick-storm fix, verbatim): queued/in_progress/waiting/pending
 * counts as active, EXCEPT a non-in_progress run whose last update is
 * older than 6h — a zombie superseded by its concurrency group.
 */
function isLiveSmRun(r, now) {
    var s = r.status ? String(r.status).toLowerCase() : '';
    if (!isActiveSmStatus(s)) return false;
    if (s !== 'in_progress' && isZombieSmRun(r, now)) return false; // zombie queued > 6h
    return true;
}

/**
 * SM-active probe (review #701, tick-storm fix): TRUE when a machine-sm.yml
 * run is queued/in_progress/waiting/pending — the SM is already about to
 * drain the queue itself, so the end-of-run self-tick must NOT stack another
 * one. Mirrors smAgent's hasActiveTargetWorkflowRun semantics: a queued run
 * older than 6h is a zombie (the concurrency group superseded it) and does
 * not count. The workflow-id form of the listing 404s for some PATs (live fa
 * 2026-09-23, same fallback as smAgent's validation-sync) — fall back to the
 * all-runs endpoint and filter by workflow path client-side. An unlistable
 * repo fails OPEN (dispatch anyway): a missed tick stalls the conveyor, a
 * duplicate one is idempotent.
 */
function hasActiveSmRun(owner, name) {
    var runs = listSmRuns(owner, name);
    if (runs === null) return false; // unlistable → fail open, the self-heal still fires
    var now = Date.now();
    for (var i = 0; i < runs.length; i++) {
        if (isLiveSmRun(runs[i] || {}, now)) return true;
    }
    return false;
}

/**
 * gh-952 (live fa 2026-10-17 06:30–08:10Z): the merge-window slot holder
 * the open list can no longer show. PR #1661 was merged by the OWNER via
 * bypass while its validation was ARMED (Quality gate / Binaries smoke
 * pending stamps) — the machine's merge path never ran, so the arm was
 * never consumed, and the merged PR vanished from github_list_prs
 * (state:'open'). The FIFO then saw neither a holder nor a released
 * slot: every approved PR deferred as 'awaiting validate-armed turn'
 * with acted: 0 while the holder could NEVER validate again. Returns
 * the recently-merged PR still carrying the merge-window arm
 * (ai_validating + pr_approved — mutexAmong parity; a dev-lane arm
 * never held the merge window), or null when no such holder exists.
 * Consulted ONLY when no OPEN PR holds the arm — a live holder owns the
 * slot and the merged history is not probed at all. Recency-bounded
 * (24h): weeks-old merged PRs with lingering labels are archaeology,
 * not a slot event. An undated body reads as not-fresh (NaN < x is
 * false) — no release.
 */
var MERGED_SLOT_HOLDER_MAX_AGE_MS = 24 * 60 * 60 * 1000;

function mergedSlotHolder(owner, name) {
    var merged = listArray(parseMcp(github_list_prs({
        workspace: owner, repository: name, state: 'merged'
    })));
    for (var i = 0; i < merged.length; i++) {
        var p = merged[i];
        var labels = labelNames(p);
        var armed = labels.indexOf('ai_validating') !== -1 && labels.indexOf('pr_approved') !== -1;
        var fresh = armed && p.merged_at &&
            (Date.now() - Date.parse(p.merged_at)) < MERGED_SLOT_HOLDER_MAX_AGE_MS;
        if (fresh) return p;
    }
    return null;
}

/**
 * END-OF-RUN SELF-TICK (owner rule 2026-10-04; live: agents#696,
 * dart#342 — the bot logged the defer line, exited acted:0, the repo
 * went event-quiet, and the validate-armed turn never came until a
 * human fired machine-sm.yml manually). A deferred approved PR with
 * acted==0 means NOTHING consumed this turn and no action of ours will
 * generate the events that re-drive the queue — fire ONE real SM tick
 * so the oldest approved PR gets its validate-armed turn. Not fired
 * when acted>0 (a merge/latch/unarm is motion — its events carry the
 * conveyor) nor when no deferred-approved was seen (nothing waits on a
 * turn). Review #701 hardening: the dispatch targets the PR's own repo
 * explicitly (--repo owner/name — gh resolves the CWD's repo, wrong in
 * multi-repo runners) and is SKIPPED when a machine-sm.yml run is
 * already queued/running (hasActiveSmRun — the active SM drains the
 * queue itself; a second tick per bot run was tick-storm amplification
 * during healthy waves). jobParams.selfTick=false disables it.
 * (gh-952: extracted verbatim from action() — the merged-slot-holder
 * release lives in the FIFO loop now, and the CRAP ratchet forbids
 * growing action; behavior is unchanged, see test_mergeBot self-tick.)
 */
function selfTickToSm(owner, name, job, deferredApproved, acted, say) {
    if (!deferredApproved || acted > 0 || job.selfTick === false) return;
    if (hasActiveSmRun(owner, name)) {
        say('⏭️ self-tick skipped (SM already active)');
        return;
    }
    try {
        cli_execute_command({
            command: 'gh workflow run machine-sm.yml -F dryRun=false --repo ' + owner + '/' + name
        });
        say('🔁 deferred approved → SM tick dispatched (self-heal)');
    } catch (eTick) {
        say('⚠️ self-tick dispatch failed: ' + ((eTick && eTick.message) || eTick));
    }
}

/**
 * gh-766 dead-head predicate (gh-1040 extraction, verbatim): an armed
 * head is stale when its rollup is pending, the PR is approved, and the
 * oldest pending evidence has been motionless past the threshold. The
 * pendingSince truthiness check is load-bearing (falsy = fail open).
 */
function isStalePending(rollup, approved, pendingSince, staleHeadMinutes, now) {
    return rollup === 'pending' && approved && pendingSince &&
        (now - pendingSince) > staleHeadMinutes * 60 * 1000;
}

/**
 * Unarm-on-staleness predicate (gh-1040 extraction, verbatim): only a
 * REALLY stale approved head is unarmed — BEHIND (base moved) or DIRTY
 * (conflicts). BLOCKED right after a workflow_run trigger means
 * 'required checks still settling' — unarming there races the check-run
 * conclusion, drops a green armed PR, and forces a full re-validation
 * cycle (live: fa pr-762, 11:36 — bot unarm on BLOCKED while the rollup
 * was green two lines above).
 */
function shouldUnarmStaleHead(ms, approved) {
    return approved && (ms === 'BEHIND' || ms === 'DIRTY');
}

/**
 * Live-open guard for the get_pr body in action()'s FIFO loop
 * (gh-1040 extraction, verbatim): a body without a number, or with an
 * explicit non-OPEN state, is a stale list entry and is skipped.
 */
function isLiveOpenPr(pr) {
    if (!pr.number) return false;
    if (!pr.state) return true;
    return String(pr.state).toUpperCase() === 'OPEN';
}

/**
 * The head sha of a PR body, verbatim shapes (gh-1040 extraction): the
 * REST body carries head.sha, older bridges a bare head string.
 */
function headShaOf(pr) {
    return pr.head && (pr.head.sha || pr.head);
}

/**
 * The ai_validating unarm, both log shapes verbatim (gh-1040
 * extraction): on success the ok line is logged and true returned; on
 * failure the failPrefix line carries the verbatim error and false is
 * returned (callers only credit acted on success). The tracker call is
 * the same single github_remove_label in the same position.
 */
function unarmValidating(owner, name, number, okLine, failPrefix, say) {
    try {
        github_remove_label({ workspace: owner, repository: name, number: number, label: 'ai_validating' });
        say(okLine);
        return true;
    } catch (e) {
        say(failPrefix + (e.message || e));
        return false;
    }
}

/**
 * The gh-766 stale-pending unarm, log line verbatim (gh-1040
 * extraction): the motionless-hours arithmetic and the skip line move
 * out of action(); returns the acted credit (1 unarmed, 0 on failure).
 */
function unarmStaleHead(owner, name, pr, pendingSince, staleHeadMinutes, say) {
    var stillHours = Math.round(((Date.now() - pendingSince) / 3600000) * 10) / 10;
    return unarmValidating(owner, name, pr.number,
        '⏭️ pr-' + pr.number + ' skipped: checks pending ' + stillHours +
        'h (> ' + (Math.round(staleHeadMinutes / 6) / 10) + 'h motionless) — unarmed, queue advances',
        '⚠️ pr-' + pr.number + ' stale-head unarm failed: ', say) ? 1 : 0;
}

/**
 * The BEHIND/DIRTY staleness unarm, log line verbatim (gh-1040
 * extraction): returns the acted credit (1 unarmed, 0 on failure).
 */
function unarmStaleHeadState(owner, name, pr, ms, say) {
    return unarmValidating(owner, name, pr.number,
        '🔓 pr-' + pr.number + ' validated head stale (' + ms + ') — unarmed, refresh follows',
        '⚠️ pr-' + pr.number + ' unarm failed: ', say) ? 1 : 0;
}

/**
 * The green-CLEAN unapproved latch (gh-1040 extraction, verbatim): unarm
 * ai_validating (failure swallowed by design), then add ai_validated —
 * the add is the acted motion; its failure is reported verbatim.
 */
function latchValidated(owner, name, pr, say) {
    try { github_remove_label({ workspace: owner, repository: name, number: pr.number, label: 'ai_validating' }); } catch (e) {}
    try {
        github_add_labels({ workspace: owner, repository: name, number: pr.number, labels: ['ai_validated'] });
        say('✅ pr-' + pr.number + ' validated (no approval yet) — ai_validated latched, review follows');
        return true;
    } catch (e) {
        say('⚠️ pr-' + pr.number + ' latch failed: ' + (e.message || e));
        return false;
    }
}

/**
 * Squash-merge attempt for an approved head (gh-1040 extraction,
 * verbatim): merges through squashMerge (one transparent retry) and
 * logs the caller's merged line on success or the verbatim refusal on
 * failure. Returns the acted credit (1 or 0).
 */
function mergeApprovedHead(owner, name, pr, mergedLine, say) {
    var m = squashMerge(owner, name, pr.number);
    if (m.merged) {
        say(mergedLine);
        return 1;
    }
    say('❌ pr-' + pr.number + ' merge refused: ' + m.error);
    return 0;
}

function squashMerge(owner, repo, number) {
    var last = null;
    for (var attempt = 1; attempt <= 2; attempt++) {
        try {
            var res = parseMcp(github_merge_pr({
                workspace: owner, repository: repo,
                pullRequestId: number, mergeMethod: 'squash'
            }));
            // GitHub returns {"merged": true} on success; anything else
            // carries a message — surface it VERBATIM (the fa pr-759 404
            // hour was debugged blind because errors printed bare).
            if (res.merged === true || res.ok === true) return { merged: true };
            last = res.message || JSON.stringify(res);
        } catch (e) {
            last = (e && e.message) || String(e);
        }
        // Retry once: transient 404/409 (stale head cache) resolves on a
        // fresh get_pr; deterministic refusals fail again with the reason.
        if (attempt === 1) github_get_pr({ workspace: owner, repository: repo, pullRequestId: number });
    }
    return { merged: false, error: last };
}

function action(params) {
    var job = (params && params.jobParams) || {};
    var target = resolveRepoTarget(job);
    var owner = target.owner, name = target.name;

    var log = [];
    function say(line) { log.push(line); console.log(line); }

    var prs = parseMcp(github_list_prs({ workspace: owner, repository: name, state: 'open' }));
    var list = listArray(prs);
    var acted = 0;
    var deferredApproved = false;
    // gh-766 dead-head skip: the FIFO head position is checked for liveness
    // every tick. An owner-'blocked' PR, or an armed APPROVED PR whose
    // checks have been motionless past staleHeadMinutes (default 120 = 2h),
    // is skipped WITH AN EXPLICIT LOG LINE and the queue advances past it
    // to the first live (validated + green + CLEAN) approved PR. A silent
    // vanish here starved the whole queue behind the head — acted: 0 for
    // over an hour while 4 approved+validated PRs waited (live fa
    // 2026-10-06: pr-1231 checks=pending over pr-1309/1311/1313/1317).
    var staleHeadMinutes = staleHeadMinutesOr(job);
    var skippedHeads = 0;
    var deadHeadPassed = false;
    // gh-952 slot release: the holder the open list can no longer see. An
    // externally-merged (owner bypass) armed PR is invisible to the scan
    // below — labels outlive the merge, the PR does not — so the FIFO
    // waited on a validate-armed turn nobody would ever hand out. When no
    // OPEN PR holds the merge-window arm, probe the merged list once: a
    // recently-merged still-armed holder means the slot is ALREADY
    // RELEASED — say so, and vacate the head position (gh-766 dead-head
    // parity: a validated candidate may take the turn on existing
    // evidence; the SM still owns arming the fresh head).
    var releasedHolder = findReleasedSlotHolder(list, owner, name);
    if (releasedHolder) {
        deadHeadPassed = true;
        say('🔓 pr-' + releasedHolder.number + ' held the merge-window slot but is MERGED — ' +
            'slot released (the armed stamps belonged to a merged PR, gh-952)');
    }

    // Owner directive 2026-10-04 ("red yields the slot") — diagnostic only:
    // once per run, when the first approved PR is deferred as FIFO-queued,
    // probe whether the ai_validating holder's validation has CONCLUDED RED
    // (an in-flight run reads 'pending' and stays silent). A red holder
    // means the SM's fail-validation should have freed the slot — the line
    // makes the starvation visible in the bot log (live fa 11:0x: #1194
    // held a concluded-red arm while #1215..#1223 queued 40+ min). The bot
    // itself NEVER acts on it (no unarm, no dispatch — SM-owned).
    var redSlotProbed = false;
    function noteRedSlotHolder(queuedNumber) {
        if (redSlotProbed) return;
        redSlotProbed = true;
        try {
            for (var h = 0; h < list.length; h++) {
                var hp = list[h];
                var hNum = (hp && (hp.number || hp.prNumber)) || 0;
                var hLabels = labelNames(hp || {});
                if (!hNum || hNum === queuedNumber) continue;
                if (hLabels.indexOf('ai_validating') === -1) continue;
                // mutexAmong parity: only APPROVED arms serialize this
                // queue — a dev-lane arm does not hold the merge-window slot.
                if (hLabels.indexOf('pr_approved') === -1) continue;
                var hHead = hp.head && (hp.head.sha || hp.head);
                if (!hHead) continue;
                if (checksRollup(String(hHead), hp, job, owner, name) === 'red') {
                    say('🚨 pr-' + hNum + ' holds slot with concluded-red validation — fail path should free it');
                }
                return; // one holder possible — probed, said or not
            }
        } catch (eRed) { /* diagnostic only — never fails the run */ }
    }

    // Oldest first — FIFO, same fairness as the SM's merge rule (#687).
    list.sort(function (a, b) { return (a.number || 0) - (b.number || 0); });

    for (var i = 0; i < list.length; i++) {
        var pr = parseMcp(github_get_pr({
            workspace: owner, repository: name, pullRequestId: list[i].number
        }));
        if (!isLiveOpenPr(pr)) continue;
        if (pr.draft) continue;
        var labels = labelNames(pr);
        var headSha = headShaOf(pr);
        if (!headSha) continue;
        if (hasLabel(labels, 'blocked')) {
            // gh-766: owner-parked (#939 semantics unchanged — the bot still
            // never acts on a blocked PR), but the skip is now EXPLICIT and
            // the head position is dead: the queue may advance past it. The
            // old bare `continue` made a blocked head invisible to the run
            // log and a poison pill for everyone queued behind it.
            say('⏭️ pr-' + pr.number + ' skipped: blocked');
            skippedHeads++;
            deadHeadPassed = true;
            continue;
        }

        var approved = hasLabel(labels, 'pr_approved');
        var validating = hasLabel(labels, 'ai_validating');
        if (!validating || hasLabel(labels, 'agent:review')) {
            // Approved-but-unarmed PRs are FIFO-queued behind the current
            // validation (validate-armed mutex, one CI at a time). Say so —
            // a silent skip is indistinguishable from a stuck pipeline for
            // the operator (live: fa 2026-09-25, pr-948/pr-963 sat silent
            // for hours while the queue was healthy).
            //
            // gh-766: dead heads skipped above (blocked / stale-pending)
            // VACATED the head position — the first approved PR behind them
            // that already carries validation evidence (the ai_validated
            // latch) takes the turn on the SAME evidence gates as the armed
            // path: green rollup on the current head + CLEAN. One advance
            // per skip-chain — the first candidate consumes it, so FIFO
            // holds for everyone behind; never-validated, mid-review,
            // draft, conflicted and not-ready candidates keep deferring.
            if (approved && !hasLabel(labels, 'agent:review')) {
                var advanced = false;
                if (deadHeadPassed && hasLabel(labels, 'ai_validated')) {
                    // consumed by the first live candidate — one advance
                    // per skip-chain, so FIFO holds for everyone behind.
                    deadHeadPassed = false;
                    var upRollup = checksRollup(String(headSha), pr, job, owner, name);
                    if (upRollup === 'green' && mergeStateOf(pr) === 'CLEAN') {
                        var gained = mergeApprovedHead(owner, name, pr,
                            '🧲 pr-' + pr.number + ' squash-merged (approved + validated + green + CLEAN — advanced past a skipped dead head)',
                            say);
                        if (gained) {
                            acted += gained;
                            advanced = true;
                        }
                    }
                }
                if (!advanced) {
                    say('⏳ pr-' + pr.number + ' approved — FIFO-queued (awaiting validate-armed turn)');
                    deferredApproved = true;
                    noteRedSlotHolder(pr.number);
                }
            }
            continue; // mid-review: SM owns it
        }
        // An armed PR is a LIVE head by default: it owns the FIFO position
        // and nobody advances past it — unless the stale-pending check
        // below declares it dead (gh-766).
        deadHeadPassed = false;
        if (pr.mergeable === false) continue; // conflicts: conflict-rework (SM) owns it

        var detail = rollupDetail(String(headSha), pr, job, owner, name);
        var rollup = detail.state;
        if (rollup !== 'green') {
            if (isStalePending(rollup, approved, detail.pendingSince, staleHeadMinutes, Date.now())) {
                // gh-766 dead head: the armed validation has been motionless
                // past the threshold and will never conclude. Unarm — it
                // frees the SM's validate-armed mutex so the next approved
                // PR gets its turn (same remedy shape as the BEHIND/DIRTY
                // unarm below) — and let the queue advance. Unapproved
                // (dev-lane) arms don't hold the merge window (mutexAmong
                // parity) and keep waiting untouched: re-dispatching a
                // slow-CI dev lane every 2h would only lose its queue spot.
                acted += unarmStaleHead(owner, name, pr, detail.pendingSince, staleHeadMinutes, say);
                skippedHeads++;
                deadHeadPassed = true;
                continue;
            }
            say('⏳ pr-' + pr.number + ' checks=' + rollup + ' — waiting');
            continue;
        }
        var ms = mergeStateOf(pr);
        if (ms !== 'CLEAN') {
            if (shouldUnarmStaleHead(ms, approved)) {
                acted += unarmStaleHeadState(owner, name, pr, ms, say);
            } else {
                say(blockedWaitLine(pr.number, ms, approved));
            }
            continue;
        }

        if (approved) {
            acted += mergeApprovedHead(owner, name, pr,
                '🧲 pr-' + pr.number + ' squash-merged (approved + green + CLEAN)', say);
        } else {
            // Green head, no approval yet: latch for the review leg.
            if (latchValidated(owner, name, pr, say)) acted++;
        }
    }

    // END-OF-RUN SELF-TICK — extracted verbatim into selfTickToSm()
    // (gh-952: the merged-slot-holder release joined action()'s loop and
    // the CRAP ratchet forbids growing action; the self-tick block moved
    // to the helper above, behavior unchanged).
    selfTickToSm(owner, name, job, deferredApproved, acted, say);

    say('mergeBot complete — acted: ' + acted + ', heads skipped: ' + skippedHeads);
    return { success: true, acted: acted, skipped: skippedHeads, log: log };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action, checksRollup: checksRollup, rollupDetail: rollupDetail, mergeStateOf: mergeStateOf, blockedWaitLine: blockedWaitLine, labelNames: labelNames };
}

/**
 * Machine SM Agent — GitHub-issues machine-loop watchdog (JSRunner).
 *
 * The dark-factory loop over GitHub issues (dev → PR → CI → rework → AI
 * review → merge → close) relies on `labeled` events to wake the
 * ai-teammate workflow. Labels added with the workflow's own GITHUB_TOKEN
 * do NOT fire `labeled` events (GitHub rule), so every machine-added
 * label — agent:rework after red CI, pr_approved after an APPROVE verdict
 * — is a dead letter unless a human re-arms it (issue #116). This agent
 * is the safety net: a deterministic reconciler (no AI CLI, no LLM) that
 * runs on a short cron tick, reads the ACTUAL state of every
 * machine-managed issue (labels, linked PR, check rollup, merge state,
 * active workflow runs) and performs whatever step the state calls for —
 * dispatching legs directly via workflow_dispatch (GITHUB_TOKEN CAN
 * dispatch; only label events are mute), updating branches, merging
 * approved PRs, closing issues whose PRs merged.
 *
 * Concurrency contract: if any AI Teammate run is queued/in_progress the
 * agent idles for the whole tick (the cron re-fires soon — short ticks,
 * no long sleeps), so parallel runs finish before new legs start and the
 * per-issue concurrency group in ai-teammate.yml never cancels mid-flight
 * work. `maxConcurrentRuns` (default 1) relaxes this when the machine can
 * afford parallel legs.
 *
 * Configuration (override priority, sm-style):
 *   1. jobParams in agents/machine_sm.json (defaults)
 *   2. .dmtools/config.js `machineSm` section (project override)
 *      { machineSm: { dryRun: true, maxConcurrentRuns: 1, ... } }
 *   3. CLI JSON override (outer `params` wrapper — same quirk as sm):
 *      dmtools run agents/machine_sm.json '{"params":{"jobParams":{"dryRun":true}}}'
 *
 * jobParams fields:
 *   dryRun            — log the plan, perform no action (default false)
 *   maxConcurrentRuns — idle unless active AI Teammate runs < this (default 1)
 *   maxReworkRounds   — mirrors ai-teammate.yml MAX_AUTO_REWORK_ROUNDS (default 2)
 *   workflowFile      — the machine workflow to dispatch (default ai-teammate.yml)
 *   branchPrefix      — machine dev-branch prefix (default 'ai/gh-')
 *   agentHandle       — assignee that marks an issue machine-managed (default 'ai-teammate')
 *   issueLimit        — how many open issues to scan per tick (default 50)
 *   closeComment      — comment posted by the close-issue safety net
 *
 * Decision core (decideActions) is pure and unit-tested; all GitHub I/O
 * goes through `gh` via cli_execute_command and is injectable/mocks-able
 * through jobParams.ghRunner for tests.
 */
'use strict';

var configLoader = require('./configLoader.js');
// gh-828 (hoisted, never lazy — the gh-823 pack-require rule): the
// post-APPROVE thread-resolution leg classifies threads through the
// reviewVerdicts pure helpers, and the machine-auth allowlist comes from
// the machineAuthor knob.
var reviewVerdictsModule = require('./common/reviewVerdicts.js');
var machineAuthorModule = require('./common/machineAuthor.js');

// ─────────────────────────────────────────────────────────────────────────────
// Pure decision core — decideActions(state, cfg) → actions[]
//
// state = {
//   issue:  { number, labels: [..], assignees: [..] },
//   pr:     null | { number, state: 'OPEN'|'MERGED'|'CLOSED',
//                    checkConclusion: 'red'|'green'|'pending'|'none',
//                    mergeState: 'CLEAN'|'BEHIND'|'DIRTY'|'BLOCKED'|'UNKNOWN',
//                    mergeable: bool|null },
//   activeRunForIssue: bool
// }
// cfg = { maxReworkRounds: int }
// ─────────────────────────────────────────────────────────────────────────────
function decideActions(state, cfg) {
    var actions = [];
    var labels = (state.issue && state.issue.labels) || [];
    var has = function (l) { return labels.indexOf(l) !== -1; };
    var maxRounds = (cfg && cfg.maxReworkRounds) || 2;

    // 'blocked' = human hold (fa #939): the official freeze switch — the
    // reconciler skips the item ENTIRELY (no dead-letter re-fire, no branch
    // update, no merge, no close) until a human removes the label.
    // Engine-level, evaluated before every other decision; the SM rule
    // engine (githubSource.matchesGuards) honors the same label.
    if (has('blocked')) {
        actions.push({ type: 'skip', reason: 'blocked — human hold; the machine skips this item entirely' });
        return actions;
    }
    if (has('needs-human')) {
        actions.push({ type: 'skip', reason: 'needs-human — waiting for a human' });
        return actions;
    }
    if (state.activeRunForIssue) {
        actions.push({ type: 'skip', reason: 'active AI Teammate run for this issue' });
        return actions;
    }

    // Rework round cap — mirrors ai-teammate.yml MAX_AUTO_REWORK_ROUNDS:
    // escalate instead of looping rework forever.
    var rounds = 0;
    labels.forEach(function (l) {
        var m = /^rework-round-(\d+)$/.exec(l);
        if (m) rounds = Math.max(rounds, parseInt(m[1], 10));
    });
    var reworkExhausted = rounds >= maxRounds;

    var pr = state.pr;
    if (!pr) {
        // No open PR and nothing merged for this issue yet.
        if (has('ai_developed')) {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'ai_developed but no open PR (dead dev run)' });
        } else if (has('agent:dev')) {
            actions.push({ type: 'dispatch', leg: 'dev',
                reason: 'agent:dev labeled, no PR yet (dead dev letter)' });
        } else if (has('agent:rework')) {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'stale agent:rework with no PR' });
        } else {
            actions.push({ type: 'skip', reason: 'no PR and no machine leg to (re)fire' });
        }
        return actions;
    }

    if (pr.state !== 'OPEN') {
        if (pr.state === 'MERGED') {
            actions.push({ type: 'closeIssue',
                reason: 'linked PR #' + pr.number + ' merged (Fixes #N safety net)' });
        } else {
            actions.push({ type: 'skip', reason: 'linked PR #' + pr.number + ' is ' + pr.state });
        }
        return actions;
    }

    if (pr.checkConclusion === 'pending') {
        actions.push({ type: 'skip', reason: 'PR #' + pr.number + ' checks pending' });
        return actions;
    }

    if (pr.checkConclusion === 'red') {
        if (reworkExhausted) {
            actions.push({ type: 'label', label: 'needs-human',
                reason: 'CI red after ' + rounds + ' rework rounds — escalating' });
        } else {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'CI red on PR #' + pr.number + (has('agent:rework')
                    ? ' (stale agent:rework — dead letter re-fire)'
                    : '') });
        }
        return actions;
    }

    // ── green below ──────────────────────────────────────────────────────────
    if (has('pr_approved')) {
        if (pr.mergeState === 'BEHIND') {
            actions.push({ type: 'updateBranch',
                reason: 'approved but behind main — updating branch' });
        } else if (pr.mergeState === 'CLEAN' || pr.mergeable === true) {
            actions.push({ type: 'merge',
                reason: 'approved + green + mergeable (merge-trigger parity)' });
        } else if (pr.mergeState === 'BLOCKED') {
            // gh-828 (live fa #1457–#1470, 2026-10-10): BLOCKED on an
            // approved green head is the unresolved-thread conversation
            // gate (gh-683 branch protection). The rework arm is withheld
            // on APPROVE+blocking=0 (gh-807) and the rework leg is the
            // only other owner of thread resolution — so the machine's own
            // non-blocking suggestion threads held every approved PR
            // BLOCKED for ~8h. Resolve them IN-TICK: gate on the head's
            // effective machine verdict record (APPROVE + census
            // blocking=0), then ack-reply + resolve each unresolved
            // machine-authored non-blocking thread (bounded, idempotent).
            // Human threads never resolve here (AC3) — they keep BLOCKED
            // and surface to humans. If threads were not the blocker
            // (e.g. a pending required check also reads BLOCKED), the leg
            // is a harmless no-op and the next tick re-evaluates.
            actions.push({ type: 'resolveSuggestionThreads',
                reason: 'approved + BLOCKED — unresolved-thread conversation gate (gh-828): resolve machine-owned non-blocking threads in-tick' });
        } else {
            actions.push({ type: 'skip',
                reason: 'approved but merge state ' + pr.mergeState });
        }
        return actions;
    }

    if (has('ai_developed') && !has('ai_pr_reviewed')) {
        actions.push({ type: 'dispatch', leg: 'review',
            reason: 'green PR #' + pr.number + ' awaits machine review' });
        return actions;
    }
    if (has('ai_pr_reviewed') && !has('pr_approved')) {
        // Reviewed but the verdict never reached approve. The review leg
        // itself labels agent:rework for CHANGES_REQUESTED verdicts; if
        // that label is present with no active run it is another dead
        // letter — re-fire it. Otherwise wait (verdict processing pending).
        if (has('agent:rework')) {
            actions.push({ type: 'dispatch', leg: 'rework',
                reason: 'stale agent:rework after review (dead letter re-fire)' });
        } else {
            actions.push({ type: 'skip',
                reason: 'reviewed, verdict not approve — awaiting rework labeling' });
        }
        return actions;
    }

    actions.push({ type: 'skip', reason: 'steady state' });
    return actions;
}

// ─────────────────────────────────────────────────────────────────────────────
// Forge I/O — delegated to the SCM-agnostic provider (common/smProvider.js);
// github and gitlab both speak the same contract.
// ─────────────────────────────────────────────────────────────────────────────
var smProviderModule = require('./common/smProvider.js');

// Parse "gh-<n>" out of a machine run display title (kept here: the pure
// core tests pin it).
function issueFromRunTitle(title) {
    var m = /gh-(\d+)/.exec(String(title || ''));
    return m ? parseInt(m[1], 10) : null;
}

function executeAction(provider, action, issue, cfg) {
    switch (action.type) {
        case 'dispatch':
            return provider.dispatchLeg(issue.number, action.leg, action.reason, cfg.workflowFile);
        case 'label':
            return provider.addIssueLabel(issue.number, action.label);
        case 'updateBranch':
            return provider.updateBranch(action.prNumber);
        case 'merge':
            return provider.merge(action.prNumber);
        case 'closeIssue':
            return provider.closeIssue(issue.number, cfg.closeComment);
        case 'resolveSuggestionThreads':
            return resolveSuggestionThreads(provider, action.prNumber, action.headSha, cfg);
        default:
            return null;
    }
}

// gh-828 — the post-APPROVE in-tick thread-resolution leg (the missing
// owner from the withheld-arm branch, live fa #1457–#1470). Gate on the
// head's effective machine verdict record — parsed with the machine-author
// allowlist (gh-828 review round 2: the marker format is public, so a
// forged APPROVE from any comment-capable identity must stay invisible) —
// via the reviewVerdicts pure selector, then per selected thread RESOLVE
// FIRST and post the ack reply only on success (review round 3: a failed
// resolve must not leave an ack behind for the next tick to duplicate).
// Idempotent (already-resolved threads are filtered by selection) and
// bounded (maxResolveThreads per tick, default 20). Fail-closed
// everywhere: no head sha, no machine logins configured, missing provider
// primitives (gitlab), or a non-APPROVE / blocking census record → zero
// resolutions. A per-thread failure is logged and never aborts the rest.
function resolveSuggestionThreads(provider, prNumber, headSha, cfg) {
    var none = { resolved: 0 };
    if (!provider || typeof provider.verdictRecords !== 'function' ||
        typeof provider.reviewThreadList !== 'function' ||
        typeof provider.replyToThread !== 'function' ||
        typeof provider.resolveThread !== 'function') {
        console.warn('  ⚠️ resolveSuggestionThreads: provider lacks the verdict/thread primitives — skipped (gitlab twin has none yet)');
        return none;
    }
    var logins = (cfg && cfg.machineLogins) || [];
    if (!headSha || !logins.length) {
        console.log('  ⏭️  resolveSuggestionThreads on PR #' + prNumber +
            ': no head sha or no machine logins configured — nothing resolves (fail closed)');
        return none;
    }
    var records = provider.verdictRecords(prNumber, { authorLogins: logins });
    var threads = provider.reviewThreadList(prNumber);
    var sel = reviewVerdictsModule.selectResolvableThreads(records, headSha, threads, {
        machineLogins: logins,
        maxThreads: (cfg && cfg.maxResolveThreads) || reviewVerdictsModule.DEFAULT_RESOLVE_THREADS_CAP
    });
    if (sel.gate !== 'approve') {
        console.log('  ⏭️  resolveSuggestionThreads on PR #' + prNumber +
            ': verdict gate "' + sel.gate + '" — nothing resolves (fail closed)');
        return none;
    }
    if (!sel.resolvable.length) {
        console.log('  ⏭️  resolveSuggestionThreads on PR #' + prNumber +
            ': no eligible threads (human ' + sel.skipped.human + ', blocking ' + sel.skipped.blocking +
            ', already resolved ' + sel.skipped.resolved + ', no id ' + sel.skipped.noThreadId + ')');
        return none;
    }
    var ack = reviewVerdictsModule.buildThreadAckReply();
    var resolved = 0;
    sel.resolvable.forEach(function (t) {
        // gh-828 review round 3: resolve FIRST, ack only on success. With
        // reply-first, a persistent resolve failure (transient GraphQL
        // error, token drift) leaves the thread unresolved; the next tick
        // re-selects it and posts another ack — one duplicate per tick,
        // unbounded. A resolved thread missing its ack is a cosmetic loss
        // the code already tolerates (replyToThread may fail after a
        // successful resolve); an unresolved thread carrying fresh acks
        // is spam.
        try {
            provider.resolveThread(prNumber, t);
            resolved++;
        } catch (eResolve) {
            console.warn('  ⚠️ resolveThread failed on PR #' + prNumber + ': ' + (eResolve.message || eResolve));
            return;
        }
        try {
            provider.replyToThread(prNumber, t, ack);
        } catch (eReply) {
            console.warn('  ⚠️ ack reply failed on a resolved thread of PR #' + prNumber + ': ' + (eReply.message || eReply));
        }
    });
    console.log('  ✅ resolveSuggestionThreads on PR #' + prNumber + ': resolved ' + resolved +
        '/' + sel.resolvable.length + ' non-blocking machine thread(s)');
    return { resolved: resolved };
}

// ─────────────────────────────────────────────────────────────────────────────
// gh-980: config/state resolution helpers extracted from action() — the
// sm-style override-before-jobParams priority, verbatim semantics.
// ─────────────────────────────────────────────────────────────────────────────

// Knob with an explicit-undefined override check: the project override wins
// even over an explicit falsy jobParams value (e.g. dryRun:false).
function pickKnob(overrideVal, pVal, dflt) {
    return overrideVal !== undefined ? overrideVal : (pVal || dflt);
}

function resolveMaxResolveThreads(override, p, dflt) {
    if (typeof override.maxResolveThreads === 'number' && override.maxResolveThreads > 0) {
        return Math.floor(override.maxResolveThreads);
    }
    if (typeof p.maxResolveThreads === 'number' && p.maxResolveThreads > 0) {
        return Math.floor(p.maxResolveThreads);
    }
    return dflt;
}

// gh-828: the post-APPROVE thread-resolution leg resolves ONLY threads
// authored by the machine identities (the gh-728 comma-separated list
// knob, same resolution chain as every other machine-keyed guard).
// Unconfigured → empty list → the leg fails closed and resolves
// nothing (human threads would otherwise be closed by the machine).
// First truthy value among three candidates — the sm-style string-knob
// defaulting pattern (override || jobParams || built-in default).
function firstDefined(a, b, c) {
    return a || b || c;
}

function resolveMachineSmConfig(p, projectConfig) {
    var override = (projectConfig && projectConfig.machineSm) || {};
    var cfg = {
        dryRun:            pickKnob(override.dryRun, p.dryRun, false),
        maxConcurrentRuns: pickKnob(override.maxConcurrentRuns, p.maxConcurrentRuns, 1),
        maxReworkRounds:   pickKnob(override.maxReworkRounds, p.maxReworkRounds, 2),
        workflowFile:      firstDefined(override.workflowFile, p.workflowFile, 'ai-teammate.yml'),
        branchPrefix:      firstDefined(override.branchPrefix, p.branchPrefix, 'ai/gh-'),
        agentHandle:       firstDefined(override.agentHandle, p.agentHandle, 'ai-teammate'),
        issueLimit:        firstDefined(override.issueLimit, p.issueLimit, 50),
        closeComment:      firstDefined(override.closeComment, p.closeComment, 'Machine SM: linked PR merged — closing the loop.')
    };
    cfg.machineLogins = machineAuthorModule.machineAuthorLogins(
        machineAuthorModule.resolveMachineAuthor(p, projectConfig));
    // gh-828 review round 4: same override-before-p priority as every other
    // machineSm knob — a project-config cap silently ignored would leave an
    // operator tuning the wrong bound.
    cfg.maxResolveThreads = resolveMaxResolveThreads(override, p,
        reviewVerdictsModule.DEFAULT_RESOLVE_THREADS_CAP);
    return cfg;
}

function resolveRepoCfg(projectConfig, p) {
    var projectRepo = projectConfig && projectConfig.repository;
    if (projectRepo && projectRepo.owner && projectRepo.repo) return projectRepo;
    if (p.repository) return p.repository;
    if (p.repo) return { owner: String(p.repo).split('/')[0], repo: String(p.repo).split('/')[1] };
    return null;
}

function loadMachineSmProjectConfig(p) {
    try {
        return configLoader.loadProjectConfig({ configPath: p.configPath }) || {};
    } catch (e) {
        return {};
    }
}

// Forge selection: scm.provider (github | gitlab) — scm.js contract.
function resolveScmCfg(projectConfig, p) {
    return (projectConfig.scm && projectConfig.scm.provider)
        ? projectConfig.scm
        : (p.scm || { provider: 'github' });
}

// Provider creation is fail-closed: the error string lands in the result.
function createSmProviderOrError(scmCfg, repoCfg) {
    try {
        return { provider: smProviderModule.createSmProvider({ scm: scmCfg, repository: repoCfg }) };
    } catch (e) {
        return { error: String(e.message || e) };
    }
}

// gh-952 (live fa 2026-10-17): a run whose linked PR is MERGED is
// archaeology, not a slot event — it can never be consumed by the loop.
// Probe result kinds: 'unknown' (issue indeterminate — never dropped),
// 'merged' (release the slot), 'live', 'error' (fail closed — keep).
function probeOrphanRun(provider, n, branchPrefix) {
    if (n === 'unknown') return { kind: 'unknown' };
    try {
        var ref = provider.findPr(n, branchPrefix);
        if (ref && ref.state === 'MERGED') return { kind: 'merged', prNumber: ref.number };
        return { kind: 'live' };
    } catch (eOrphan) {
        return { kind: 'error' };
    }
}

function filterLiveActiveIssues(provider, activeIssues, branchPrefix) {
    return activeIssues.filter(function (n) {
        var probe = probeOrphanRun(provider, n, branchPrefix);
        if (probe.kind === 'merged') {
            console.log('  🔓 gh-' + n + ': the active run\'s linked PR #' + probe.prNumber +
                ' is MERGED (owner bypass) — it can never be consumed; releasing the slot (gh-952)');
            return false;
        }
        if (probe.kind === 'error') {
            console.warn('  ⚠️  gh-' + n + ': orphan-slot probe failed — keeping the run in the count (fail closed)');
        }
        return true;
    });
}

// One issue through the reconcile loop: probe the linked PR, run the pure
// decision core, execute (or plan, in dryRun) every action. Returns the
// per-issue counters action() aggregates.
function buildIssueState(provider, issue, branchPrefix, activeSet) {
    var prRef = provider.findPr(issue.number, branchPrefix);
    var pr = prRef && prRef.state === 'OPEN' ? provider.prStatus(prRef.number) : prRef;
    return {
        prRef: prRef,
        pr: pr,
        state: {
            issue: issue,
            pr: pr,
            activeRunForIssue: !!activeSet[issue.number] || !!activeSet['unknown']
        }
    };
}

function planActionFields(a, prRef, pr) {
    a.prNumber = prRef ? prRef.number : null;
    a.headSha = (pr && pr.headSha) || null;
}

function logAction(issue, a, cfg) {
    console.log('  ' + (cfg.dryRun ? '[dry] ' : '') + '▶️  gh-' + issue.number + ' ' +
        a.type + (a.leg ? ':' + a.leg : '') + ' — ' + a.reason);
}

// Executes one non-skip action unless dryRun; returns 'planned' | 'acted' | 'failed'.
function applyIssueAction(provider, issue, cfg, a) {
    if (cfg.dryRun) return 'planned';
    try {
        executeAction(provider, a, issue, cfg);
        return 'acted';
    } catch (e) {
        console.error('  ❌ gh-' + issue.number + ' ' + a.type + ' failed: ' + (e.message || e));
        return 'failed';
    }
}

function reconcileIssue(provider, issue, cfg, activeSet) {
    var counters = { acted: 0, dispatched: 0, skipped: 0, failures: 0 };
    var built = buildIssueState(provider, issue, cfg.branchPrefix, activeSet);
    var acts = decideActions(built.state, cfg);
    for (var i = 0; i < acts.length; i++) {
        var a = acts[i];
        if (a.type === 'skip') {
            counters.skipped++;
            console.log('  ⏭️  gh-' + issue.number + ': ' + a.reason);
            continue;
        }
        planActionFields(a, built.prRef, built.pr);
        logAction(issue, a, cfg);
        var outcome = applyIssueAction(provider, issue, cfg, a);
        if (outcome === 'failed') { counters.failures++; continue; }
        counters.acted++;
        if (a.type === 'dispatch') counters.dispatched++;
    }
    return counters;
}

// ─────────────────────────────────────────────────────────────────────────────
// JSRunner entry point
// ─────────────────────────────────────────────────────────────────────────────
function action(params) {
    var p = params.jobParams || params;
    var projectConfig = loadMachineSmProjectConfig(p);

    var cfg = resolveMachineSmConfig(p, projectConfig);
    var repoCfg = resolveRepoCfg(projectConfig, p);

    if (!repoCfg || !repoCfg.owner || !repoCfg.repo) {
        console.error('❌ machineSm: repository required (.dmtools/config.js repository or jobParams.repo owner/repo)');
        return { success: false, error: 'Missing repo' };
    }

    var providerResult = createSmProviderOrError(resolveScmCfg(projectConfig, p), repoCfg);
    if (providerResult.error !== undefined) {
        console.error('❌ machineSm: ' + providerResult.error);
        return { success: false, error: providerResult.error };
    }
    var provider = providerResult.provider;

    console.log('Machine SM — ' + repoCfg.owner + '/' + repoCfg.repo + ' [' + provider.provider + ']' +
        (cfg.dryRun ? ' [DRY RUN]' : '') + ' (cap ' + cfg.maxConcurrentRuns + ', rounds ' + cfg.maxReworkRounds + ')');

    // 1. Global concurrency gate — the user contract: with parallel runs
    //    in flight, wait them out; the cron tick re-fires soon.
    var activeIssues = provider.activeMachineRuns(cfg.workflowFile);
    var liveActiveIssues = filterLiveActiveIssues(provider, activeIssues, cfg.branchPrefix);
    if (liveActiveIssues.length >= cfg.maxConcurrentRuns) {
        console.log('  ⏳ idle — active machine run(s) for ' +
            (liveActiveIssues.join(', ') === 'unknown' ? 'this project' : 'issue(s) ' + liveActiveIssues.join(', ')) +
            '; waiting for the next tick');
        return { success: true, idle: true, waitingFor: liveActiveIssues };
    }

    // 2. Reconcile every machine-managed issue through the provider.
    var machineLabels = ['agent:dev', 'agent:rework', 'agent:review',
        'ai_developed', 'ai_pr_reviewed', 'pr_approved', 'needs-human'];
    var issues = provider.listMachineIssues(machineLabels, cfg.agentHandle, cfg.issueLimit);

    var dispatched = 0, acted = 0, skipped = 0, failures = 0;
    var activeSet = {};
    liveActiveIssues.forEach(function (n) { activeSet[n] = true; });

    issues.forEach(function (issue) {
        var counters = reconcileIssue(provider, issue, cfg, activeSet);
        acted += counters.acted;
        dispatched += counters.dispatched;
        skipped += counters.skipped;
        failures += counters.failures;
    });

    console.log('\n══ Machine SM complete — acted: ' + acted + ' (dispatched ' + dispatched +
        '), skipped: ' + skipped + ', failures: ' + failures + ' ══');
    return { success: failures === 0, acted: acted, dispatched: dispatched, skipped: skipped, failures: failures };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        decideActions: decideActions,
        issueFromRunTitle: issueFromRunTitle,
        resolveSuggestionThreads: resolveSuggestionThreads,
        resolveMachineSmConfig: resolveMachineSmConfig,
        resolveRepoCfg: resolveRepoCfg,
        probeOrphanRun: probeOrphanRun,
        filterLiveActiveIssues: filterLiveActiveIssues
    };
}

